// Made-up sample for "Try a sample archive": a small Weebly site archive built by _build/make-sample.mjs from
// _tests/fixtures.mjs (sampleSpec). Every name, text and picture in it is invented.
const B64 = '';
export function sampleBytes() {
  const bin = atob(B64);
  const out = new Uint8Array(bin.length);
  for (let i = 0; i < bin.length; i++) out[i] = bin.charCodeAt(i);
  return out;
}
